  "testability": {
    "p_testable": 0.2,
    "blocking_constraints": [
      {
        "code": "RTM_SELECTION",
        "text": "Defining PNR failure by possession outcome (low points, turnover) selects on the lower tail of the distribution, causing subsequent possessions to regress to the mean regardless of play type."
