  "prior_work": {
    "already_answered": "partly",
    "cited": [
      "FAM:SF13",
      "FAM:SF-APPA-001",
      "FAM:SF-APPS-058",
      "FAM:SF-APPA-067"
    ],
    "summary": "Prior studies on within-game adaptation and counter strategies (SF13, SF-APPA-001) found that apparent lifts are artefactual due to regression to the mean and selection bias. Defensive scheme labeling efforts (SF-APPS-058) failed because confident labels were too rare. Adversarial re-routing (SF-APPA-067) showed that first-stage lifts shrink substantially. These findings collectively indicate that any study defining 'failure' by outcome and measuring subsequent lift is at high risk of producing a spurious positive result."
  },
  "risks": [
    {
      "code": "RTM_SELECTION",
      "text": "Likely the dominant risk: selecting PNR possessions that 'failed' (low points) will bias upward the apparent lift of any subsequent action because outcomes will naturally regress toward the mean."
